25	/** „Schöne“ Achse: {von, bis, schritt, ticks[]} */
26	export function achse(min, max, anzahl = 5) {
27	  if (!Number.isFinite(min) || !Number.isFinite(max)) return { von: 0, bis: 1, ticks: [0, 1] };
28	  if (min === max) {
29	    min -= 1;
30	    max += 1;
31	  }
32	  const roh = (max - min) / anzahl;
33	  const p = 10 ** Math.floor(Math.log10(roh));
34	  const schritt = [1, 2, 2.5, 5, 10].map((f) => f * p).find((s) => s >= roh) || 10 * p;
35	  const von = Math.floor(min / schritt) * schritt;
36	  const bis = Math.ceil(max / schritt) * schritt;
37	  const ticks = [];
38	  for (let t = von; t <= bis + schritt / 2; t += schritt) ticks.push(Math.round(t * 1e6) / 1e6);
39	  return { von, bis, schritt, ticks };
40	}
