190	function useZeiger(n, W, P) {
191	  const [hover, setHover] = useState(null);
192	  const band = (W - P.l - P.r) / Math.max(1, n);
193	  const ausZeiger = (e) => {
194	    const box = e.currentTarget.getBoundingClientRect();
195	    const px = ((e.clientX - box.left) / box.width) * W;
196	    return Math.max(0, Math.min(n - 1, Math.floor((px - P.l) / band)));
197	  };
198	  const tasten = (e) => {
199	    if (e.key === "ArrowRight") setHover((h) => Math.min(n - 1, (h ?? -1) + 1));
200	    else if (e.key === "ArrowLeft") setHover((h) => Math.max(0, (h ?? n) - 1));
201	    else if (e.key === "Escape") setHover(null);
202	    else return;
203	    e.preventDefault();
204	  };
205	  return { hover, setHover, band, ausZeiger, tasten };
206	}
