export function Plot({ breite, hoehe, anzahl, indexAusPx, info, fadenkreuz, beschreibung, dunkel = false, children, svgKlasse, rand = "auto" }) {
  const [aktiv, setAktiv] = useState(null);
  const [fokus, setFokus] = useState(false);
  const flaeche = useRef(null);
  const daten = aktiv != null && aktiv < anzahl ? info(aktiv) : null;

  useEffect(() => {
    if (aktiv != null && aktiv >= anzahl) setAktiv(null);
  }, [aktiv, anzahl]);

  const ausZeiger = (e) => {
    const box = e.currentTarget.getBoundingClientRect();
    const x = ((e.clientX - box.left) / box.width) * breite;
