      console.log("anlage", pfad);
    }
    const r = await p.goto(B + pfad, { waitUntil: "load", timeout: 180000 });
    await p.waitForTimeout(3500);
    const info = await p.evaluate(() => ({
      ueber: document.documentElement.scrollWidth - window.innerWidth,
      diagramme: document.querySelectorAll("svg[data-diagramm]").length,
      breiten: [...document.querySelectorAll("svg[data-diagramm]")].slice(0, 6).map((s) => `${s.getAttribute("width")}/${Math.round(s.parentElement.getBoundingClientRect().width)}`),
    }));
    let tast = "";
    const flaeche = p.locator("[aria-roledescription='Diagramm']").first();
    if (await flaeche.count()) {
      await flaeche.scrollIntoViewIfNeeded();
      await p.waitForTimeout(900);
      await flaeche.focus();
      await p.keyboard.press("ArrowRight");
      await p.keyboard.press("ArrowRight");
      await p.waitForTimeout(250);
      const tip = await p.locator(".ov-tooltip").first().textContent().catch(() => null);
      const ansage = await flaeche.locator("xpath=..").locator("[aria-live]").first().textContent().catch(() => null);
      tast = `Tooltip: ${tip?.slice(0, 120)} | Ansage: ${ansage?.slice(0, 120)}`;
      if (shot) {
        const fig = flaeche.locator("xpath=ancestor::figure[1]");
        await fig.screenshot({ path: fileURLToPath(new URL(`./shots/t4_${name}_${breite}.png`, import.meta.url)) });
      }
      const knopf = p.getByRole("button", { name: "Tabelle" }).first();
      if (await knopf.count()) {
        await knopf.click();
        await p.waitForTimeout(400);
        tast += ` | Tabellenzeilen: ${await p.locator("figure table tbody tr").count()}`;
      }
    }
    console.log(r.status(), name, pfad, JSON.stringify(info), "\n  ", tast, fehler.length ? "\n" + fehler.join("\n") : "");
    await p.close();
  }
} finally {
  await b.close();
}
