      const w = Math.floor(e.contentRect.width);
      if (w > 0) setBreite((alt) => (Math.abs(alt - w) >= 1 ? w : alt));
    });
    ro.observe(el);
    return () => ro.disconnect();
  }, [el]);
  return [setEl, breite];
}

